# Problem: locate target in a sorted list (classic binary search).
# Maintain [lo, hi] bracket; halve each step based on midpoint comparison.
def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid  # found
        elif arr[mid] < target:
            lo = mid + 1  # target is in upper half
        else:
            hi = mid - 1  # target is in lower half
    return -1
```

