# Problem: longest strictly increasing subsequence (subsequence != substring).
# DP: for each i, dp[i] = LIS length ending at index i.
# Look at all j < i with nums[j] < nums[i] and take the best dp[j] + 1.
def length_of_lis(nums):
    if not nums:
        return 0
    dp = [1] * len(nums)  # every index alone is a length-1 subsequence
    for i in range(len(nums)):
        for j in range(i):
            if nums[j] < nums[i]:  # strict increase enables extension
                if dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1
    return max(dp)
```

