# Problem: longest common prefix of multiple strings.
# Start with first string as candidate prefix; shrink from the right while any string fails startswith.
def longest_common_prefix(strs):
    if not strs:
        return ''
    prefix = strs[0]
    for s in strs[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ''  # no common prefix possible
    return prefix
