# Problem: count connected components in undirected graph.
# Union-Find approach: union each edge's endpoints; count distinct roots.
# Path compression in find() keeps it near-constant amortised.
def count_components(n, edges):
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path compression
            x = parent[x]
        return x
    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb  # merge
    return sum(1 for i in range(n) if find(i) == i)
```

