# Problem: bucket words by their first character.
# defaultdict avoids the key-exists check; one pass over words is enough.
def group_by_first(words):
    from collections import defaultdict
    groups = defaultdict(list)
    for w in words:
        if w:
            groups[w[0]].append(w)
