# Problem: longest run of '0's in a binary string.
# Walk once tracking the current zero-run; reset on '1'; remember the max.
def longest_zero_sequence(s):
    best = current = 0
    for c in s:
        if c == '0':
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best
