# Problem: count connected components of 1s with 4-neighbor adjacency.
# DFS from each unvisited land cell, marking visited; one component per DFS launch.
def count_islands(grid):
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
        if r < 0 or c < 0 or r >= rows or c >= cols:
            return
        if visited[r][c] or grid[r][c] != 1:
            return
        visited[r][c] = True
        dfs(r+1, c); dfs(r-1, c); dfs(r, c+1); dfs(r, c-1)
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                dfs(r, c)
                count += 1
    return count
```

