# Problem: full recursive flatten of nested lists.
# Recurse on list items, collect scalars. Use isinstance to detect lists.
def flatten_deep(lst):
    out = []
    for x in lst:
        if isinstance(x, list):
            out.extend(flatten_deep(x))
