# Problem: count decodings of digit string where 1-26 = A-Z.
# DP from left: dp[i] = dp[i-1] (single digit if non-zero) + dp[i-2] (pair if 10-26).
def decode_ways(s):
    if not s or s[0] == '0':
        return 0
    dp = [0] * (len(s) + 1)
    dp[0] = dp[1] = 1
    for i in range(2, len(s) + 1):
        if s[i - 1] != '0':
            dp[i] += dp[i - 1]
        two = int(s[i - 2:i])
        if 10 <= two <= 26:
            dp[i] += dp[i - 2]
    return dp[-1]
```

