# Problem: count connected groups of '1' cells in a 2D char grid.
# BFS/DFS from each unvisited land cell, marking visited as we go.
# Stack-based DFS avoids deep recursion on big grids.
def num_islands(grid):
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1' and not visited[r][c]:
                count += 1
                stack = [(r, c)]
                while stack:
                    x, y = stack.pop()
                    if 0 <= x < rows and 0 <= y < cols and not visited[x][y] and grid[x][y] == '1':
                        visited[x][y] = True
                        stack.extend([(x+1,y),(x-1,y),(x,y+1),(x,y-1)])
    return count
```

