# Problem: rotate n x n matrix 90 clockwise without an aux array.
# Two-step: transpose then reverse each row.
def rotate_matrix_in_place(matrix):
    n = len(matrix)
    for i in range(n):
        for j in range(i + 1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
    for row in matrix:
        row.reverse()
    return matrix
```

