# Problem: evaluate reverse Polish notation with int math (trunc toward zero for /).
# Stack: push numbers, pop two on operator, push result. int(a/b) truncates correctly for negatives.
def eval_rpn(tokens):
    stack = []
    for t in tokens:
        if t in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if t == '+': stack.append(a + b)
            elif t == '-': stack.append(a - b)
            elif t == '*': stack.append(a * b)
            else: stack.append(int(a / b))
        else:
            stack.append(int(t))
    return stack[0]
```

