# Problem: encode integer 1-3999 as a Roman numeral.
# Greedy: subtract the largest fitting value-symbol pair, append symbols, repeat.
def int_to_roman(n):
    pairs = [(1000,'M'),(900,'CM'),(500,'D'),(400,'CD'),(100,'C'),(90,'XC'),(50,'L'),(40,'XL'),(10,'X'),(9,'IX'),(5,'V'),(4,'IV'),(1,'I')]
    out = []
    for v, s in pairs:
        while n >= v:
            out.append(s)
            n -= v
    return ''.join(out)
